using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace DarkCipher.AgentControl.App.Appearance;

/// <summary>
/// The application icon at run time. The same app.ico is embedded in the exe (ApplicationIcon: Explorer, taskbar pinning,
/// Start menu shortcuts, the MSI's Add/Remove Programs entry) and set on every window (title bar, Alt+Tab, taskbar button).
/// The large PNG is used on the About card. Assets are generated by tools/DarkCipher.AgentControl.IconBuilder.
/// </summary>
public static class ApplicationIconService
{
    public static readonly Uri IcoUri = new("pack://application:,,,/DarkCipherAgentControl;component/Assets/AppIcon/app.ico", UriKind.Absolute);
    public static readonly Uri LargePngUri = new("pack://application:,,,/DarkCipherAgentControl;component/Assets/AppIcon/app-256.png", UriKind.Absolute);

    private static ImageSource? _windowIcon;
    private static ImageSource? _large;

    /// <summary>The multi-frame icon for windows (WPF picks the best frame for the title bar and taskbar).</summary>
    public static ImageSource WindowIcon => _windowIcon ??= Load(IcoUri);

    /// <summary>256 px artwork for the About card.</summary>
    public static ImageSource LargeImage => _large ??= Load(LargePngUri);

    public static void ApplyTo(Window window)
    {
        if (window.Icon is null) window.Icon = WindowIcon;
    }

    /// <summary>Number of frames in the embedded icon and their pixel sizes (self-test and Settings → About).</summary>
    public static IReadOnlyList<int> FrameSizes()
    {
        var decoder = BitmapDecoder.Create(IcoUri, BitmapCreateOptions.None, BitmapCacheOption.OnLoad);
        return decoder.Frames.Select(f => f.PixelWidth).OrderBy(x => x).ToList();
    }

    private static ImageSource Load(Uri uri)
    {
        var frame = BitmapFrame.Create(uri, BitmapCreateOptions.None, BitmapCacheOption.OnLoad);
        frame.Freeze();
        return frame;
    }
}
